import Foundation
@testable import Business
import Domain
import Testing

// MARK: - Capture

/// Thread-safe recorder for (CleanupState, PipelineState) pairs emitted by the
/// coordinator's consolidated `onStateChange` callback.
private final class StatePairRecorder: @unchecked Sendable {
    private let lock = NSLock()
    private var storage: [(CleanupState, PipelineState)] = []

    func append(_ cleanup: CleanupState, _ pipeline: PipelineState) {
        lock.lock()
        storage.append((cleanup, pipeline))
        lock.unlock()
    }

    var pairs: [(CleanupState, PipelineState)] {
        lock.lock()
        defer { lock.unlock() }
        return storage
    }
}

// MARK: - Fakes

private struct EmptyStorageError: Error {}

/// Read repository that always throws, driving the coordinator's failure paths
/// without needing on-disk fixtures.
private actor ThrowingReadRepository: RecordingReadRepository {
    func getRecording(id _: RecordingID) async throws -> StoredRecording { throw EmptyStorageError() }
    func listRecordings(limit _: Int?, offset _: Int?) async throws -> [RecordingSummary] { [] }
    func totalStorageSize() async throws -> Int64 { 0 }
    func listPendingSessions() async throws -> [RecordingID] { [] }
    func listAllRecordingsWithMetadata() async throws -> [RecordingMetadata] { [] }
    func listNeedsRetranscription() async throws -> [RecordingID] { [] }
}

private actor NoopTranscriptWriter: TranscriptWriteRepository {
    func updateTranscript(id _: RecordingID, transcript _: TranscriptionResult) async throws {}
    func saveDraftTranscript(draftText _: String, for _: RecordingID) async throws {}
}

private actor NoopTranscriptionEngine: TranscriptionEngine {
    func loadModel(_: ModelID) async throws {}
    func transcribe(samples _: [Float], context _: TranscriptionContext) async throws -> TranscriptionSegment {
        TranscriptionSegment(id: SegmentID("seg"), text: "t", startTime: 0, endTime: 1, confidence: 1, isFinal: true, sequenceNumber: 0)
    }
    func isReady() async -> Bool { true }
    func warmUp() async throws {}
}

private struct NoopSampleLoader: AudioSampleLoader {
    func loadSamples(from _: URL) async throws -> [Float] { [] }
}

private actor NoopDiarizationEngine: DiarizationEngine {
    func diarize(samples _: [Float], config _: DiarizationConfig) async throws -> DiarizationResult {
        throw EmptyStorageError()
    }
}

private actor NoopDiarizationWriter: DiarizationWriteRepository {
    func saveDiarizedTranscript(_: DiarizedTranscript, for _: RecordingID) async throws {}
}

private actor NoopSummarizationEngine: SummarizationEngine {
    func loadModel(_: ModelID) async throws {}
    func summarize(text _: String, config _: SummaryConfig) async throws -> MeetingSummary {
        throw EmptyStorageError()
    }
    func isReady() async -> Bool { false }
}

// MARK: - Fixtures

private func makeCoordinator() -> PipelineCoordinator {
    let cleanup = CleanupTranscriptionUseCase(
        transcription: NoopTranscriptionEngine(),
        sampleLoader: NoopSampleLoader(),
        reader: ThrowingReadRepository(),
        writer: NoopTranscriptWriter()
    )
    let diarize = DiarizeMeetingUseCase(
        diarization: NoopDiarizationEngine(),
        sampleLoader: NoopSampleLoader(),
        reader: ThrowingReadRepository(),
        writer: NoopDiarizationWriter()
    )
    let summarize = SummarizeMeetingUseCase(summarization: NoopSummarizationEngine())
    return PipelineCoordinator(
        cleanupTranscribe: cleanup,
        diarizeMeeting: diarize,
        summarizeMeeting: summarize
    )
}

private func makeTranscriptionResult() -> TranscriptionResult {
    TranscriptionResult(
        segments: [],
        fullText: "live",
        processingTime: 0,
        modelId: ModelID("m"),
        recordedAt: Date(timeIntervalSince1970: 0),
        computeUnit: .cpuOnly,
        passType: .live
    )
}

/// Polls until `condition` is true or ~2s elapse, yielding between checks.
private func waitUntil(_ condition: @Sendable () -> Bool) async {
    for _ in 0..<200 {
        if condition() { return }
        try? await Task.sleep(nanoseconds: 10_000_000)
    }
}

// MARK: - Tests

@Suite("task-011 — PipelineCoordinator onStateChange SSOT callback")
struct PipelineCoordinatorStateChangeTests {
    @Test("cleanup transitions emit consolidated (CleanupState, PipelineState) pairs in order")
    func cleanupTransitionsEmitConsolidatedPairs() async throws {
        let recorder = StatePairRecorder()
        let coordinator = makeCoordinator()
        await coordinator.setOnStateChange { cleanup, pipeline in
            recorder.append(cleanup, pipeline)
        }

        _ = await coordinator.runCleanupPass(recordingId: RecordingID("rec-1"))

        let pairs = recorder.pairs
        #expect(pairs.count == 2, "expected .running then .idle cleanup transitions, got \(pairs.count) emissions")
        #expect(pairs.first?.0.isRunning == true, "first emission must carry CleanupState.running")
        if case .idle = pairs.first?.1 {} else {
            Issue.record("first emission must carry the current PipelineState (.idle)")
        }
        if case .idle = pairs.last?.0 {} else {
            Issue.record("failed cleanup must emit CleanupState.idle as the final transition")
        }
    }

    @Test("pipeline transitions emit consolidated pairs carrying the current cleanup state")
    func pipelineTransitionsEmitConsolidatedPairs() async throws {
        let recorder = StatePairRecorder()
        let coordinator = makeCoordinator()
        await coordinator.setOnStateChange { cleanup, pipeline in
            recorder.append(cleanup, pipeline)
        }

        await coordinator.startPipeline(for: RecordingID("rec-2"), liveTranscription: makeTranscriptionResult())
        await waitUntil { recorder.pairs.count >= 2 }

        let pairs = recorder.pairs
        #expect(pairs.count >= 2, "expected .diarizing then .failed pipeline transitions")
        #expect(pairs.first?.1.isDiarizing == true, "first emission must carry PipelineState.diarizing")
        if case .failed = pairs.last?.1 {} else {
            Issue.record("throwing diarization must emit PipelineState.failed as the final transition")
        }
        if case .idle = pairs.last?.0 {} else {
            Issue.record("pipeline transitions must carry the current CleanupState (.idle)")
        }
    }

    @Test("cancelAll emits a single consolidated (.idle, .idle) pair")
    func cancelAllEmitsIdlePair() async throws {
        let recorder = StatePairRecorder()
        let coordinator = makeCoordinator()
        await coordinator.setOnStateChange { cleanup, pipeline in
            recorder.append(cleanup, pipeline)
        }

        await coordinator.cancelAll()

        let pairs = recorder.pairs
        #expect(pairs.count == 1, "cancelAll must emit exactly one consolidated pair")
        if case .some((.idle, .idle)) = pairs.first {} else {
            Issue.record("cancelAll must emit (.idle, .idle)")
        }
    }
}

