import Foundation
import Testing

// MARK: - Repo root

/// Walks up from this file to the monorepo root. This test file lives at
/// `Record-CrossPlatform-Foundation/Tests/PackageWiring/`, so the repo root is
/// three directories up.
private func repoRoot() -> URL {
    URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent() // PackageWiring
        .deletingLastPathComponent() // Tests
        .deletingLastPathComponent() // Record-CrossPlatform-Foundation
        .deletingLastPathComponent() // repo root
}

private func appForkExists(_ fileName: String) -> Bool {
